import{_ as n,a0 as o,w as p,s as d,ao as r,I as l,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"7 個好玩的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"7 個好玩的 Linux 命令 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7 個好玩的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7 個好玩的 Linux 命令 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211111 7 Linux commands to use just for fun","title":"7 個好玩的 Linux 命令","tag":"202111","desc":""},"relativePath":"202111/20211111 7 Linux commands to use just for fun.md","filePath":"[post].md"}'),h={name:"202111/20211111 7 Linux commands to use just for fun.md"};function c(u,s,g,k,b,f){const a=o("Link");return p(),d("div",null,[s[15]||(s[15]=r(`<h1 id="_7-個好玩的-linux-命令" tabindex="-1">7 個好玩的 Linux 命令 <a class="header-anchor" href="#_7-個好玩的-linux-命令" aria-label="Permalink to “7 個好玩的 Linux 命令”">​</a></h1><blockquote><p>這些好玩的 Linux 命令也有它的用處。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/16/164838m35s5q81t353sxq3.jpg" alt=""></p><p>Linux 的命令列可以説是資深用户和系統管理員的小窩。然而，Linux 不僅僅是大量的枯燥工作。Linux 是由愛玩的人開發的，他們還創造了一系列搞笑的命令。當你想輕鬆一下的時候，就可以自己試着這些。</p><h3 id="蒸汽機車" tabindex="-1">蒸汽機車 <a class="header-anchor" href="#蒸汽機車" aria-label="Permalink to “蒸汽機車”">​</a></h3><p>隨便什麼時候，你可以使用 <code>sl</code> 命令使一輛<ruby>蒸汽機車<rt>Steam Locomotive</rt></ruby>在你的終端上跑過。可以用你的軟件包管理器安裝這輛蒸汽機車。例如，在 Fedora 上可以這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install sl</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/locomotive_0.png" alt="由符號和字符組成的蒸汽機車引擎圖" title="Steam locomotive"></p><h4 id="實際用途" tabindex="-1">實際用途 <a class="header-anchor" href="#實際用途" aria-label="Permalink to “實際用途”">​</a></h4><p>據我所知，<code>sl</code> 命令確實只是為了好玩。你對 <code>sl</code> 有什麼有趣的用途嗎？請在評論中告訴我。</p><p>（LCTT 譯註：<code>sl</code> 的實際用途就是提醒你 <code>ls</code> 打錯了。🤣）</p><h3 id="壁爐" tabindex="-1">壁爐 <a class="header-anchor" href="#壁爐" aria-label="Permalink to “壁爐”">​</a></h3><p>點燃一座壁爐來温暖你的心和你的終端吧，<code>aafire</code> 命令會播放一段壁爐的動畫。你可以用你的軟件包管理器安裝 <code>aafire</code>。在 Debian、Mint、 Elementary 之類的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install libaa-bin</span></span></code></pre></div><p>在 Fedora、CentOS 之類的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install aalib</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/fireside.png" alt="由文字符號和字符組成的火的黑白圖像" title="fireside"></p><h4 id="實際用途-1" tabindex="-1">實際用途 <a class="header-anchor" href="#實際用途-1" aria-label="Permalink to “實際用途”">​</a></h4><p>這個動畫是向你的團隊或老闆傳達一切即將化為烏有的微妙方式。</p><h3 id="是的" tabindex="-1">是的 <a class="header-anchor" href="#是的" aria-label="Permalink to “是的”">​</a></h3><p>你可以使用 <code>yes</code> 命令打印出一串文字，直到用 <code>Ctrl+C</code> 強行停止。例如，我是一個 Buffalo Bills 的球迷，所以我選擇用 <code>yes</code> 命令打印出一串無盡的 “Buffalo Bills”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes Buffalo Bills</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/bills.png" alt="畫面上重複顯示的是一行行 Buffalo Bills（左側邊緣略微被切斷）" title="Yes command"></p><h4 id="實際用途-2" tabindex="-1">實際用途 <a class="header-anchor" href="#實際用途-2" aria-label="Permalink to “實際用途”">​</a></h4><p>你可以用這個命令來向腳本輸送確認信息，這樣，當腳本停頓下來要求確認時，它就會自動收到 <code>yes</code>。例如，想像一下，你運行的一個腳本經常停下來問你確認：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ foo</span></span>
<span class="line"><span>Are you sure you want to do this? Y/n  Y</span></span>
<span class="line"><span>Are you really sure? y/N  Y</span></span>
<span class="line"><span>But are you really? y/N</span></span></code></pre></div><p>你可以通過向命令傳遞 <code>yes</code> 來自動接受這些信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes | foo</span></span></code></pre></div><p>另外，你也可以用 <code>yes</code> 來自動拒絕信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes no | foo</span></span></code></pre></div><h3 id="命運" tabindex="-1">命運 <a class="header-anchor" href="#命運" aria-label="Permalink to “命運”">​</a></h3><p>通過安裝 <code>fortune</code> 命令，你可以就可以得到命運的指點。<code>fortune</code> 會打印出一段隨機的、可能有意義的話語（LCTT 譯註：來自命運的指點）。</p><p>用你的軟件包管理器安裝 <code>fortune</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install fortune</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fortune-mod</span></span></code></pre></div><p>命運命令有許多數據集，它可以從中提取各種話語。例如，你可以從文學作品或科幻電視節目 《Firefly》中獲得名人名言，或者從笑話、關於 Linux 的技巧等中選擇。在你的資源庫中搜索 <code>fortune</code>，看看你的發行版提供了哪些數據集。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune</span></span>
<span class="line"><span>Johnson&#39;s law:</span></span>
<span class="line"><span>  Systems resemble the organizations that create them.</span></span></code></pre></div><h4 id="實際用途-3" tabindex="-1">實際用途 <a class="header-anchor" href="#實際用途-3" aria-label="Permalink to “實際用途”">​</a></h4><p>你可以用命運來生成一個偽隨機數。沒有足夠的熵來使它在密碼學上安全，但當你需要一個意外的數字時，你可以用來計算字符或單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune | wc --chars</span></span>
<span class="line"><span>38</span></span>
<span class="line"><span>$ fortune | wc --words</span></span>
<span class="line"><span>8</span></span>
<span class="line"><span>$ fortune | wc --chars</span></span>
<span class="line"><span>169</span></span></code></pre></div><h3 id="彩虹貓" tabindex="-1">彩虹貓 <a class="header-anchor" href="#彩虹貓" aria-label="Permalink to “彩虹貓”">​</a></h3><p>彩虹貓（<code>lolcat</code>）是一個將文件或標準輸入連接到標準輸出的程序（就像一般的 <code>cat</code> 命令），並在其中加入彩虹色。你可以用管道將其他命令的輸出連接到 <code>lolcat</code>，這樣就可以為結果加上彩虹色。</p><p>下面是 <code>lolcat -h</code> 的幫助輸出的結果。</p><p><img src="https://opensource.com/sites/default/files/uploads/lolcat_rainbow.png" alt="屏幕上的文字被染成了彩虹的漸變色" title="lolcat"></p><p>（LCTT 譯註：我知道 <code>cat</code> 是 <code>catch</code>。）</p><h3 id="fig-來信-和橫幅" tabindex="-1">“FIG 來信”和橫幅 <a class="header-anchor" href="#fig-來信-和橫幅" aria-label="Permalink to ““FIG 來信”和橫幅”">​</a></h3><p>“FIG 來信”（FIGlet）來源於 Frank、Ian 和 Glenn 信件中的簽名藝術。這個命令（<code>figlet</code>）和橫幅命令（<code>banner</code>）可以幫你創建簡單的 ASCII 文本橫幅。下面是一個 CentOS 系統的文本橫幅：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ figlet centos.com</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/figlet_centos.png" alt="由符號和字符組成的閲讀 “centos.com” 的文本橫幅" title="figlet text banner"></p><p>將 <code>figlet</code> 連接到 <code>lolcat</code>，可以得到一個彩色的橫幅：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ figlet centos.com | lolcat</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/lolcat_figlet_centos.png" alt="用 lolcat 將 “centos.com” 的文字橫幅渲染成彩虹色" title="Figlet with lolcat effects"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ banner Hello World</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/hello_world_0.png" alt="用英鎊符號拼出的 “Hello World” 橫幅" title="Hello World banner"></p><h4 id="實際用途-4" tabindex="-1">實際用途 <a class="header-anchor" href="#實際用途-4" aria-label="Permalink to “實際用途”">​</a></h4><p><code>figlet</code> 和 <code>banner</code> 都是提醒用户他們正在登錄的系統的簡單方法。就像許多系統管理員、網頁設計師和雲開發人員一樣，當你和幾十台服務器一起工作時，這很有幫助。</p><h3 id="電子語音" tabindex="-1">電子語音 <a class="header-anchor" href="#電子語音" aria-label="Permalink to “電子語音”">​</a></h3><p>你可以通過安裝電子語音（<code>espeak</code>）來為你的命令列添加語音功能。</p><p>一旦 <code>espeak</code> 安裝完畢，調高你的電腦的音量，聽你的機器和你説話，會有一些樂趣。電子語音是一個軟件語音合成器，有幾個不同的語音庫可用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ espeak &quot;Linux is the best operating system.”</span></span></code></pre></div><h3 id="有趣的命令" tabindex="-1">有趣的命令 <a class="header-anchor" href="#有趣的命令" aria-label="Permalink to “有趣的命令”">​</a></h3><p>請查閲所有這些命令的手冊，以探索所有的可能性和變化。你最喜歡哪些好玩的命令，它們在現實世界中是否也有用途？請在評論中分享你的最愛。</p><hr>`,64)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/11/fun-linux-commands"},{default:t(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/11/fun-linux-commands",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/don-watkins"},{default:t(()=>[...s[2]||(s[2]=[e("Don Watkins",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=n(h,[["render",c]]);export{x as __pageData,C as default};
